function conditionReasons(conditions){const names={'expired':'지속시간 만료','not-applied':'선행 효과 미부여','other-target':'다른 대상에 효과 부여','partial-charge':'최대 차지 미충족'};const counts={};for(const c of conditions.filter(c=>c.status==='no'))counts[c.reason]=(counts[c.reason]||0)+1;return Object.entries(counts).map(([k,v])=>(names[k]||'기타')+' '+v+'건').join(' · ');}
