 q('#sim-empty').hidden=!!build.length;q('#sim-work').hidden=!build.length;q('#sim-pin').disabled=!build.length;q('#sim-export').disabled=!build.length;
 evidence();if(!build.length){result=null;return;}
 result=Sim.run(D,build,profile,horizon);comparison=baseline?Sim.run({...D,baseSlots:baseline.baseSlots},baseline.ids,profile,horizon):null;
 q('#sim-equipment').textContent='기본 장착: '+(D.baseSlots.map(id=>byId(id)?.name).join(' · ')||'없음')+' / 개방 신식: '+(result.schedule.active.join(' · ')||'없음');
 q('#sim-play').disabled=!!result.schedule.missing.length;q('#sim-pin').disabled=!!result.schedule.missing.length;q('#sim-seek').disabled=!!result.schedule.missing.length;
 q('#sim-seek').max=horizon;q('#sim-seek').value=0;q('#sim-unpin').hidden=!baseline;
 if(result.schedule.missing.length){q('#sim-validation').hidden=false;q('#sim-validation').innerHTML='<strong>시뮬레이션을 시작할 수 없습니다.</strong><p>'+result.schedule.missing.map(esc).join(' · ')+'</p>'+(result.validation?.issues.length?'<button id="sim-fix-equipment">궁극기에 맞게 기본 장착 맞추기</button>':'');q('#sim-coverage').textContent='장착 조건 또는 필수 자료를 확인해 주세요. 이전 계산값은 표시하지 않습니다.';q('#sim-assumptions').textContent='조건을 충족하지 않는 궁극기는 시전·집계하지 않습니다.';q('#sim-metrics').innerHTML='<p class="sim-warning">계산 보류: '+result.schedule.missing.map(esc).join(' · ')+'</p>';q('#sim-verdict').textContent='장착 조건 또는 필수 자료가 충족되지 않아 계산을 중단했습니다.';q('#sim-rows').innerHTML='';q('#sim-timeline').innerHTML='';q('#sim-comparison').innerHTML='';draw();return;}
 const m=result.metrics;
 q('#sim-coverage').textContent='처치량·예상 체력은 계산하지 않습니다. '+(result.excluded.length?'부분 계산: '+result.excluded.join(' / ')+' 제외.':'공격 크기와 타격 간격은 추정값입니다.');
 q('#sim-metrics').innerHTML=[['무리 접촉률',pct(m.coverage),`${m.unique} / ${m.opportunities}마리 · 반복 배치 포함`],['평균 적중 대상',f(m.perHit)+'명','계산 가능한 타격 1회 기준'],['근접 노출',f(m.exposure)+'명','1.6m 안의 평균 몹 수 · 처치 미반영'],['조건 충족 적중',f(m.conditionPass)+'건',`불충족 ${m.conditionFail} · 미확인 ${m.conditionUnknown}`]].map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');
 const noArea=result.rows.filter(r=>r.geometry.kind==='unknown').map(r=>r.name),support=build.map(byId).filter(s=>[...(s.buffs||[]),...(s.conditions||[]).map(c=>c.result),...(s.gameDetail?.buffs||[]).map(b=>b.name)].some(x=>/회복|보호막|피해 감소/.test(x))||s.id==='s067');
 const advice=[];if(m.coverage<70&&!result.excluded.length)advice.push(`모델상 외곽 접촉 부족: ${m.opportunities-m.unique}마리는 계산에 포함된 공격에 맞지 않았습니다. 첫 원거리 공격과 주변 공격의 순서를 비교하세요.`);if(m.perHit!==null&&m.perHit<2&&!result.excluded.length)advice.push('적중이 소수 대상에 집중됩니다. 단일·전방 공격 비중과 몹이 접근하기 전 광역기 사용을 확인하세요.');if(m.exposure>=4)advice.push(`평균 ${f(m.exposure)}마리가 근접 영역에 있습니다. 밀집 이득과 피격 부담이 함께 커지는 조건입니다.`);if(m.conditionFail)advice.push(`조건 불충족 ${m.conditionFail}건 · ${conditionReasons(result.conditions)}. 자세한 적용·만료 시점은 리포트에 기록합니다.`);if(result.rage)advice.push(`연타 격노: 공간 적중을 반영하면 최대 ${result.rage.max}중첩, 3초 공백으로 ${result.rage.resets}회 소멸합니다. 한 타격에 여러 몹을 맞혀도 1회로 계산합니다.`);advice.push(`방어·회복 관련 도술 ${support.length}개 (${support.map(s=>s.name).join(' · ')||'없음'}). 보호막 흡수량·치유량과 적 피해 공식이 없어 생존 판정은 보류합니다.`);
 q('#sim-verdict').innerHTML=advice.map(t=>`<p>${esc(t)}</p>`).join('')+`<p class="sim-warning">${result.excluded.length?`일부 계산 제외: ${esc(result.excluded.join(' / '))}`:'타격 간격과 공격 범위의 수치가 추정값인 비교 모델입니다.'}</p>`;
 renderComparison();renderTimeline();
 q('#sim-rows').innerHTML=result.rows.map(r=>{const s=byId(r.id),yes=r.conditions.filter(c=>c.status==='yes').length,no=r.conditions.filter(c=>c.status==='no').length,un=r.conditions.filter(c=>c.status==='unknown').length;return `<tr><td><span class="sim-skill-name">${icon(s)}<span><b>${esc(r.name)}</b><small>${esc(s.basic?.cast)} · ${f(s.basic?.cooldown)}초 · 사거리 ${f(s.basic?.range)}m</small></span></span></td><td>${r.geometry.label}${r.geometry.sizeAssumed?'<small>크기 가정</small>':''}${r.geometry.capAssumed?'<small>상한 5명 가정</small>':''}</td><td>${r.casts}</td><td>${r.hitChecks?f(r.targetHits/r.hitChecks)+'명':'—'}</td><td>${r.hitChecks&&!r.unknown.includes('피해 계수')?f(r.coefficient)+'%':'미계산'}</td><td>${r.conditions.length?`충족 ${yes} / 불충족 ${no}${un?` / 미확인 ${un}`:''}`:'조건 판정 없음'}</td><td>${r.unknown.length?`<span class="sim-warning">${esc(r.unknown.join(' · '))} 미확인</span>`:'참고 자료 · 추정 간격'}<small>${esc(r.geometry.basis)}</small></td></tr>`;}).join('');
 q('#sim-assumptions').innerHTML=`<ul><li>영상은 배치 유형과 체력 관측의 근거입니다. 화면 좌표를 실제 거리로 보정한 복제 환경은 아닙니다. 영상의 장착 구성·시작 쿨타임을 현재 빌드에 덮어쓰지 않습니다.</li><li>12마리, 접근 속도 0.9m/s, 근접 반응 1.8m, 정지 거리 0.8~1.16m, 20초마다 새 배치로 재시험합니다. 모두 비교를 위한 가정이며 영상의 몹 수·이속·리젠 주기를 측정한 값이 아닙니다.</li><li>몬스터 처치·HP·리젠을 계산하지 않습니다. 휩쓸어 베기의 돌진은 첫 추정 타격까지 직선 이동으로 계산하며 일반 추격 이동은 계산하지 않습니다. 근접 노출은 실제 받는 피해가 아닙니다. 사거리 밖에서도 예정 시전은 진행되고 적중만 실패합니다. 실제 자동 사냥의 이동·예약 규칙과 다를 수 있습니다.</li><li>사거리와 공격 반경은 별도 값입니다. 원형 반경 2~3m, 대상 중심 반경 2m, 전방 120°, 직선 폭 1.3m, 전이 거리 3m는 가정입니다. 범위 상한 미확인은 5명으로 시험합니다.</li><li>기본 피해계수는 도감 원자료입니다. 강화·돌파·격노 피해 보너스·치명타·방어력·지속 피해·추가 피해를 적용하지 않으므로 실전 딜 순위로 사용할 수 없습니다. 계수 자료가 없으면 0 피해로 단정하지 않고 제외합니다.</li><li>효과 조건은 동일 몹에 남은 기본 부여 효과 또는 자신 효과로 판정합니다. 부여는 기존 자료의 시작/종료 시점, 지속시간을 사용합니다. 최대 차지는 실제 시전 일정의 차지 시간 또는 강압을 검사합니다. 자신에게 시전 시 부여하는 효과는 공격 형상과 독립적으로 계산합니다. 조건으로 다시 생기는 효과와 복합 조건, 소모, 해제, 추가 피해량은 계산하지 않습니다.</li><li>쿨타임·저장 횟수·개방 신식은 기존 계산기를 공유합니다. 충전 가득·자원 0으로 시작하며 매 시전 후 앞순위 사용 가능 도술을 다시 찾습니다. 신식 자원 계산은 공간 적중 실패에 따른 획득 손실까지 반영하지 않습니다.</li><li>영혼 소용돌이 등의 미확인 장판 틱은 즉시 다중 적중으로 바꾸지 않습니다. 평타·장판·지속 피해의 격노 유지 기여는 제외합니다. 영혼 소용돌이에 강제 몹 당기기 효과를 임의로 부여하지 않습니다.</li><li>가상 몹 1마리 번호는 각 20초 시험 안에서만 유지됩니다. 파쇄 등 약화 효과는 맞은 몹에게만 적용합니다.</li></ul>${result.issues.map(t=>`<p>${esc(t)}</p>`).join('')}`;
 draw();
